// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    Attacker att;

    function setUp() public {
        c = new Reentrance();
        att = new Attacker(c);
    }

    function testFuzz_property(uint256 b, uint256 a) public {
        b = bound(b, 1, 1e30);
        a = bound(a, 1, 1e30);
        att.setAmounts(b, a);
        vm.deal(address(att), b + a);
        bool ok;
        try att.trigger() { ok = true; } catch { ok = false; }
        // Rule: the reentrant addToBalance inside withdrawBalance is always blocked,
        // so the withdraw (and hence the whole trigger) MUST revert.
        assertTrue(!ok);
    }
}

contract Attacker {
    Reentrance c;
    uint256 b;
    uint256 a;
    bool stealing;

    constructor(Reentrance _c) { c = _c; }

    function setAmounts(uint256 _b, uint256 _a) external { b = _b; a = _a; }

    function trigger() external {
        c.addToBalance{value: b}();
        stealing = true;
        c.withdrawBalance();
        stealing = false;
    }

    receive() external payable {
        if (stealing) {
            // re-enter addToBalance while withdrawBalance is mid-flight
            c.addToBalance{value: a}();
        }
    }
}
